// n8n Code Node
const input = $input.first().json.body.location; // e.g., "next to player Mauri67"

function parseLocation(input) {
    const coordMatch = input.match(/^(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)$/);
    if (coordMatch) {
        return {
            type: 'coordinates',
            x: parseFloat(coordMatch[1]),
            y: parseFloat(coordMatch[2]),
            z: parseFloat(coordMatch[3])
        };
    }

    const playerMatch = input.match(/(?:next\s+to\s+)?player\s+(\w+)/i);
    if (playerMatch) {
        return {
            type: 'player',
            name: playerMatch[1]
        };
    }

    return {
        type: 'landmark',
        name: input.trim()
    };
}

const location = parseLocation(input);
return { location };

const status = $json;
return {
  Position: {
    x: Math.floor(status.position?.x || 0),
    y: Math.floor(status.position?.y || 64),
    z: Math.floor(status.position?.z || 0)
  }
}

const targetLocation = $('Teleport Workers').first().json.buildLocation;
const tasks = $input.first().json;
const targetInfo = $('Webhook').first().json.body.targetInfo || {};
const sessionId = $('Webhook').first().json.body.sessionId || 'combat_session';

const COMBAT_RADIUS = 20;
const OFFSET_DISTANCE = 5;
const MIN_TEAMMATE_SPACING = 3;

const rallyPoint = {
  x: Math.floor(targetLocation.x),
  y: Math.floor(targetLocation.y),
  z: Math.floor(targetLocation.z)
};

const getCardinalDirection = (angleRadians) => {
  const normalized = ((angleRadians % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
  if (normalized < Math.PI / 4 || normalized >= 7 * Math.PI / 4) return 'east';
  if (normalized < 3 * Math.PI / 4) return 'north';
  if (normalized < 5 * Math.PI / 4) return 'west';
  return 'south';
};

const soldierNames = Object.keys(tasks).sort((a, b) => {
  const numA = parseInt(a.match(/\d+/)?.[0] || 0);
  const numB = parseInt(b.match(/\d+/)?.[0] || 0);
  return numA - numB;
});

const numSoldiers = soldierNames.length;
const updatedTasks = {};

soldierNames.forEach((soldierName, index) => {
  const angleRadians = (index / numSoldiers) * 2 * Math.PI;

  const startX = Math.floor(rallyPoint.x + Math.cos(angleRadians) * OFFSET_DISTANCE);
  const startZ = Math.floor(rallyPoint.z + Math.sin(angleRadians) * OFFSET_DISTANCE);
  const startY = rallyPoint.y;

  const cardinalDirection = getCardinalDirection(angleRadians);
  const otherSoldiers = soldierNames.filter(s => s !== soldierName);

  let task = tasks[soldierName];

  // Update position line
  const newPosition = `You start ${OFFSET_DISTANCE} blocks ${cardinalDirection} of the target at coordinates (${startX}, ${startY}, ${startZ}).`;
  task = task.replace(
    /POSITION:[\s\S]*?(?=\n\nTARGET:|TARGET:)/,
    `POSITION: ${newPosition}\n\n`
  );

  // Add combat zone info (simple format)
  const combatZoneInfo = `

COMBAT ZONE:
- Your Start Position: (${startX}, ${startY}, ${startZ})
- Rally Point: (${rallyPoint.x}, ${rallyPoint.y}, ${rallyPoint.z})
- Max Chase Distance: ${COMBAT_RADIUS} blocks from rally point
- Your Approach: ${cardinalDirection} side

TEAMMATES: ${otherSoldiers.join(', ') || 'None'}
- Keep ${MIN_TEAMMATE_SPACING}+ blocks from teammates
- Stay on YOUR side of target`;

  // Append combat zone info before REMINDERS
  if (task.includes('REMINDERS:')) {
    task = task.replace('REMINDERS:', `${combatZoneInfo}\n\nREMINDERS:`);
  } else {
    task += combatZoneInfo;
  }

  updatedTasks[soldierName] = task;
});

return {
  tasks: updatedTasks,
  combatMetadata: {
    sessionId: sessionId,
    rallyPoint: rallyPoint,
    combatRadius: COMBAT_RADIUS,
    soldierCount: numSoldiers
  }
};

const taskDivision = $('Webhook').first().json.body.taskDivision;
const buildRequest = $('Webhook').first().json.body.combatRequest;
const location = $('Webhook').first().json.body.location || "the target area";
const targetInfo = $('Webhook').first().json.body.targetInfo || {};
const codePattern = $('Webhook').first().json.body.codePattern || {};

// Extract target name for code template
const targetName = targetInfo.primaryTarget || "hostile mob";

let coordinatedTasks = {};

Object.entries(taskDivision).forEach(([workerName, task]) => {
  // Format equipment info
  const equipment = task.equipment || {};
  const equipmentStr = [
    equipment.weapon ? `Weapon: ${equipment.weapon}` : null,
    equipment.armor ? `Armor: ${equipment.armor}` : null,
    equipment.offhand ? `Offhand: ${equipment.offhand}` : null
  ].filter(Boolean).join(', ');

  // Format tactics as numbered list
  const tacticsStr = (task.tactics || [])
    .map((t, i) => `${i + 1}. ${t}`)
    .join('\n');

  // Format constraints as bullet points (use simple dash instead of bullet)
  const constraintsStr = (task.constraints || [])
    .map(c => `- ${c}`)
    .join('\n');

  // Build the banned patterns list (simple format)
  const bannedPatterns = (codePattern.banned || [
    'bot.pathfinder',
    'GoalNear',
    'GoalBlock',
    'GoalFollow',
    'bot.navigate'
  ]).map(p => `BANNED: ${p}`).join('\n');

  // Build the required patterns list (simple format)
  const requiredPatterns = (codePattern.required || [
    'Object.values(bot.entities).find()',
    'bot.lookAt(target.position)',
    'bot.attack(target)',
    'skills.wait(bot, 300)'
  ]).map(p => `USE: ${p}`).join('\n');

  coordinatedTasks[workerName] = `COMBAT MISSION: ${buildRequest}

Location: Near ${location}
Role: ${workerName}
Combat Role: ${(task.combatRole || 'soldier').toUpperCase()}

OBJECTIVE: ${task.objective}

POSITION: ${task.position}

TARGET: ${task.targetAssignment}

EQUIPMENT: ${equipmentStr || 'Use whatever is in inventory'}

TACTICS:
${tacticsStr || 'Engage target with melee attacks'}

RETREAT CONDITION: ${task.retreatCondition || 'health below 6 hearts (bot.health < 12)'}

CONSTRAINTS:
${constraintsStr || '- Do not pursue beyond combat zone'}

BANNED CODE (DO NOT USE - WILL BREAK):
${bannedPatterns}

REQUIRED CODE PATTERNS:
${requiredPatterns}

ATTACK CODE TEMPLATE (ACTIVE DEBUG VERSION):
console.log('[${workerName}] === COMBAT START ===');
console.log('[${workerName}] Position:', bot.entity.position);

const weapon = bot.inventory.items().find(i => i.name.includes('sword')) || bot.inventory.items().find(i => i.name.includes('axe')) || null;
console.log('[${workerName}] Weapon:', weapon ? weapon.name : 'NONE (fists)');
if (weapon) await bot.equip(weapon, 'hand');

const allEntities = Object.values(bot.entities).filter(e => e.name);
console.log('[${workerName}] All entities I see:', allEntities.slice(0, 10).map(e => e.name + '(' + Math.floor(e.position.distanceTo(bot.entity.position)) + 'm)').join(', '));

let target = Object.values(bot.entities).find(e => e.name && e.name.toLowerCase().includes('${targetName.toLowerCase()}') && e.position.distanceTo(bot.entity.position) < 50);
console.log('[${workerName}] Target ${targetName}:', target ? 'FOUND at ' + Math.floor(target.position.distanceTo(bot.entity.position)) + ' blocks' : 'NOT FOUND');

if (target) {
  console.log('[${workerName}] Starting attack loop');
  let hits = 0;
  while (target && target.isValid) {
    if (bot.health < 12) {
      console.log('[${workerName}] Low health, retreating');
      await skills.moveAway(bot, 10);
      break;
    }
    await bot.lookAt(target.position);
    await bot.attack(target);
    hits++;
    if (hits % 3 === 0) console.log('[${workerName}] Hits: ' + hits);
    await skills.wait(bot, 300);
    target = bot.entities[target.id];
  }
  console.log('[${workerName}] Combat done, total hits: ' + hits);
} else {
  console.log('[${workerName}] ERROR: No ${targetName} found within 50 blocks!');
}

console.log('[${workerName}] Holding position');

REMINDERS:
- You are ALREADY positioned - do NOT use pathfinder
- bot.attack() automatically walks into melee range
- If you write pathfinder anywhere the code will BREAK
- Use the EXACT code template above including all console.log lines`;
});

return coordinatedTasks;
